function solve() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let sign = 1;
        if (buffer[offset] === 45) { // '-'
            sign = -1;
            offset++;
        }
        let res = 0;
        while (offset < buffer.length && buffer[offset] >= 48 && buffer[offset] <= 57) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res * sign;
    }

    const n = nextInt();
    if (n === null) return;

    const MAXN = n + 5;
    const keys = new Float64Array(MAXN);
    const priority = new Float32Array(MAXN);
    const count = new Int32Array(MAXN);
    const size = new Int32Array(MAXN);
    const left = new Int32Array(MAXN);
    const right = new Int32Array(MAXN);

    let nodeCount = 0;
    let root = 0;

    function update(u) {
        size[u] = count[u] + size[left[u]] + size[right[u]];
    }

    function rotateRight(y) {
        const x = left[y];
        left[y] = right[x];
        right[x] = y;
        update(y);
        update(x);
        return x;
    }

    function rotateLeft(x) {
        const y = right[x];
        right[x] = left[y];
        left[y] = x;
        update(x);
        update(y);
        return y;
    }

    function insert(u, val) {
        if (u === 0) {
            nodeCount++;
            const id = nodeCount;
            keys[id] = val;
            priority[id] = Math.random();
            count[id] = 1;
            size[id] = 1;
            left[id] = 0;
            right[id] = 0;
            return id;
        }
        if (val === keys[u]) {
            count[u]++;
            size[u]++;
            return u;
        } else if (val < keys[u]) {
            left[u] = insert(left[u], val);
            if (priority[left[u]] > priority[u]) {
                u = rotateRight(u);
            }
        } else {
            right[u] = insert(right[u], val);
            if (priority[right[u]] > priority[u]) {
                u = rotateLeft(u);
            }
        }
        update(u);
        return u;
    }

    function countLE(val) {
        let ans = 0;
        let curr = root;
        while (curr !== 0) {
            if (keys[curr] <= val) {
                ans += size[left[curr]] + count[curr];
                curr = right[curr];
            } else {
                curr = left[curr];
            }
        }
        return ans;
    }

    let prevP = 0;
    let output = '';

    for (let i = 0; i < n; i++) {
        const x = nextInt();
        const y = nextInt();

        const xr = x + prevP;
        const yr = y + prevP;

        const d = xr * xr + yr * yr;
